/**
 * Origin webhook channel pack for agent-serve.
 *
 * ```ts
 * import { defaultOriginAuth, originChannel } from "@grok/agent-sdk/channels/origin";
 *
 * export default originChannel({
 *   cursorAccount: { repos: ["owner/repo"] },
 *   onPullRequest: (ctx) => ({ auth: defaultOriginAuth(ctx) }),
 *   onComment: (ctx) => ({ auth: defaultOriginAuth(ctx) }),
 * });
 * ```
 *
 * Direct webhook mode verifies Standard-Webhooks v1ed signatures **and**
 * binds `envelope.appId` to {@link OriginChannelOptions.appId} (or
 * `AGENT_SERVE_ORIGIN_APP_ID`). v1ed alone is not channel auth — Origin
 * signs every app's deliveries with the same JWKS. Pass
 * `{ cursorAccount: true }` to receive events from
 * `serve({ cursor: { events: true } })` after `/v0/scm-events`
 * (`provider: "origin"`) already verified them. The turn principal is
 * `origin-webhook` plus the Origin actor — not the Cursor subscriber —
 * matching GitHub's `github-webhook` pattern.
 */
export { createOriginClient, cursorSessionTokenProvider, DEFAULT_ORIGIN_PUBLIC_API_BASE_URL, DEFAULT_ORIGIN_RPC_BASE_URL, OriginApiError, originAppTokenProvider, originPublicApiBaseUrl, originRpcBaseUrl, resolveCursorSessionExchangeUrl, resolveOriginAppCredentialParts, resolveOriginAppCredentials, } from "./api.js";
export { buildOriginBinding } from "./binding.js";
export { bindOriginChecks, createOriginCheck, originCheckKeyFromName, resumeOriginCheck, } from "./checks.js";
export { CURSOR_ORIGIN_MAX_REPOS, getOriginCursorAccountRuntime, parseCursorOriginRepoScope, registerOriginCursorAccountRuntime, } from "./cursor-account.js";
export { buildDefaultOriginEvents, formatOriginOutboundComment, ORIGIN_OUTBOUND_MARKER, } from "./defaults.js";
export { deriveOriginWebhookEvents, ORIGIN_CHANNEL_KIND } from "./events.js";
export { defaultOriginAuth, defaultOriginPullRequestDispatch, defaultOriginPullRequestMessage, defaultOriginTitle, dispatchOriginWebhook, envOriginAppId, findOriginChannelTargets, getOriginChannelOptions, handleOriginWebhookRequest, originChannel, originContinuationKey, originIngressExtractPayload, parseOriginPullRequestEvent, parseOriginWebhookEnvelope, } from "./origin-channel.js";
export { buildV1edSignedContentDigest, cacheControlMaxAgeMs, cacheControlStaleIfErrorMs, DEFAULT_ORIGIN_API_BASE_URL, fetchOriginJwks, OriginJwksUnavailableError, V1ED_SIGNATURE_VERSION, verifyOriginWebhook, verifyV1edWebhookPayload, } from "./origin-webhook.js";
export { ORIGIN_COMMENT_REACTIONS, SET_ORIGIN_COMMENT_REACTION_PATH, setOriginCommentReaction, } from "./reactions.js";
export { emptyOriginChannelState, originChannelStateForEvent } from "./state.js";
